async function main(ctx) {
  const resp = ctx.lastOutputOf('get_zones') || {};
  const zones = resp.body || [];

  // Organize zones by type
  const organized = {
    serp: [],
    web_unlocker: [],
    residential: [],
    isp: [],
    datacenter: [],
    mobile: [],
    other: [],
    all: zones
  };

  zones.forEach(zone => {
    const name = String(zone.zone || zone.name || '').toLowerCase();
    const type = String(zone.plan_type || zone.type || '').toLowerCase();

    if (name.includes('serp') || type.includes('serp')) {
      organized.serp.push(zone);
    } else if (name.includes('unlocker') || type.includes('unlocker')) {
      organized.web_unlocker.push(zone);
    } else if (type.includes('res') || type.includes('residential')) {
      organized.residential.push(zone);
    } else if (type.includes('isp')) {
      organized.isp.push(zone);
    } else if (type.includes('dc') || type.includes('datacenter')) {
      organized.datacenter.push(zone);
    } else if (type.includes('mobile')) {
      organized.mobile.push(zone);
    } else {
      organized.other.push(zone);
    }
  });

  return organized;
}
